@font-face {
  font-family: 'WPP Bold';
  src:  url('https://atl-csc.s3.amazonaws.com/data/5f0478b0edc858c7ed2b07a3/5f047abeedc858c7ed2b07aa/layoutrepo%24layout/5fbe424324543f44d21948c2/files/WPP-Bold.woff2') format('woff2'),
        url('https://atl-csc.s3.amazonaws.com/data/5f0478b0edc858c7ed2b07a3/5f047abeedc858c7ed2b07aa/layoutrepo%24layout/5fbe424324543f44d21948c2/files/WPP-Bold.woff') format('woff');
  font-display: swap;
}

@font-face {
  font-family: 'WPP Light';
  src:  url('https://atl-csc.s3.amazonaws.com/data/5f0478b0edc858c7ed2b07a3/5f047abeedc858c7ed2b07aa/layoutrepo%24layout/5fbe424324543f44d21948c2/files/WPP-Light.woff2') format('woff2'),
        url('https://atl-csc.s3.amazonaws.com/data/5f0478b0edc858c7ed2b07a3/5f047abeedc858c7ed2b07aa/layoutrepo%24layout/5fbe424324543f44d21948c2/files/WPP-Light.woff') format('woff');
  font-display: swap;
}

body {
  margin: 20px 0 0 0;  
}

a,
.refine ul li.link-more {
    color: #000050;
}

.message-warning {
  display: none !important;
}

.job-listing-full li a, 
.job-listing li a {
  color: #000050;
}

h1,
h2,
h3,
h4,
h5,
h6,
.main-pic__heading,
.refine-subheading,
strong,
.job-listing li a {
  font-family: "WPP Bold", sans-serif;
}

body,
input,
button,
select,
textarea,
.btn,
.form-control {
  font-family: "WPP Light", sans-serif;
}

.form__alert {
    border: 0;
    background-color: #e6ebef;
}

.form__alert .form-header {
  margin-bottom: 10px;
  font-size: 14px;
  text-transform: uppercase;
}

.form__alert p {
  margin-bottom: 20px;
}

.form__alert p a {
  color: #000;
}

.form__alert .form-group {
  width: auto;
  margin-right: 10px;
}

.form__alert input[type="text"] {
    width: 100%;
    height: 36px;
    line-height: 36px;
    font-size: 14px;
    box-shadow: 0 1px 1px #ccc;
}

body .form__alert .btn {
    width: auto;
    padding: 0;
    height: 36px;
    line-height: 36px;
    font-size: 14px;
    background-color: transparent;
    border: 0;
    color: #000;
}
.pager span {
    background-color: #000050;
    color: #fff;
}
.pager a:hover {
    background-color: #000050;
    border-color: #000050
}
.btn-primary{
    color: #fff;
    background-color: #000050;
    border-color: #000050;
    border-radius:5px;
}
}

.form__search .btn-primary {
  background-color: #000050;
  border-color: #000050;
  border-radius: 5px;
}

@media (max-width: 767px) { 
  body,
  .holder-inner .form__search {
     margin-top: 0;
  }

  .page {
    padding-bottom: 0;;
  }

  .form__alert__default {
    margin-bottom: 0;
  }

  .form__alert__default {
    border: 0;
    background-color: #e6ebef;
}

.form__alert__default .form-header {
  margin-bottom: 10px;
  font-size: 14px;
  text-transform: uppercase;
}

.form__alert__default p {
  margin-bottom: 20px;
}

.form__alert__default p a {
  color: #000;
}

.form__alert__default .form-group {
  width: auto;
  margin-right: 10px;
}

.form__alert__default input[type="text"] {
    width: 100%;
    height: 36px;
    line-height: 36px;
    font-size: 14px;
    box-shadow: 0 1px 1px #ccc;
}

body .form__alert__default .btn {
    width: auto;
    padding: 0;
    height: 36px;
    line-height: 36px;
    font-size: 14px;
    background-color: transparent;
    border: 0;
    color: #000;
  }
}

@media (min-width: 768px) {
  .form__alert .form-group { 
    width: 240px;
  }
  .form__alert input[type="text"] {
    max-width: 100%;
  }
  .browse-header, .form-header, .job-listing__header {
    font-size: 20px;
  }
}

.main-pic .form__search .form-control:focus {
  border-bottom-color: #000050;
}
.btn-success{
    color: #fff;
    background-color: #000050;
    border-color: #000050;
    border-radius:5px;
}
.form__alert .form-control, .form__search .form-control {
    height: 50px;
    padding: 2px 12px 0;
    line-height: 50px;
    font-size: 20px;
    border-radius: 5px;
}
.form__alert__default .form-control {
    margin-bottom: 10px;
    box-shadow: none;
    border: 1px solid #ccc;
    border-radius: 5px;
}
.form__alert__default .btn:hover {
    background-color: #000050;
    border-color: #000050;
}

.btn-primary:hover {
    background-color: #000050;
    border-color: #000050;
}

.form-control:focus {
    -webkit-box-shadow: 0 2px 4px rgba(0,0,0,.22);
    -moz-box-shadow: 0 2px 4px rgba(0,0,0,.22);
    box-shadow: 0 2px 4px rgba(0,0,0,.22);
}

#btn-apply-top { display: none; }

